import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { gradeOn, usePeople } from '../people/people';
import { csvValue } from '../people/export.slot';
import { chargedOf, useRates } from '../rates/rates';
import { periodOn, usePeriods } from '../periods/periods';
import { useSettings } from '../roles/roles';
import { dueByOf, useClaims } from './claims';

// The claims export button: downloads every claim on the sheet as CSV — people in list order (retired people
// included, shown or not), each person's claims oldest first — with person, number, date, amount, due, status and
// period as the claim's row shows them. Quoting and line ends as the people export.
function ExportClaims() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const periods = usePeriods();
  const settings = useSettings();
  const today = useSheetToday();
  if (!user || !sheet) return null;
  const download = () => {
    const lines = [['person', 'number', 'date', 'amount', 'due', 'status', 'period']];
    for (const p of people.data ?? []) {
      // The sheet's claims come newest first.
      const mine = (claims.data ?? []).filter((c) => c.personId === p.id).reverse();
      for (const c of mine) {
        lines.push([p.name, c.number ?? '', c.date, c.amount,
          chargedOf(c, rates.data, gradeOn(p, c.date), settings.data, today), c.status,
          periodOn(periods.data, dueByOf(c))?.name ?? '']);
      }
    }
    const csv = lines.map((l) => l.map(csvValue).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `claims-${sheet}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };
  return (
    <button type="button" data-testid="export-claims" onClick={download}>
      Export claims (CSV)
    </button>
  );
}

export const contribution = HomeMain.fill({ order: 19.1, Component: ExportClaims });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

/** A sheet's pool as the store holds it: a trimmed name, on the sheet at most once, and its members, each a person
 *  of the sheet at most once with a share percent. `totalShare` is the members' shares added up, a retired member's
 *  (one with a retirement date set, whatever the date) counting as given; `balanced` is whether it is exactly 100.00. */
export type Pool = { id: number; name: string; totalShare: string; balanced: boolean; members: PoolMember[] };

/** A pool's member: the person, or another pool (`poolId`; the other null), its name, its share (two decimals) and its
 *  cut of the pool's pot (two decimals; "" when the pool is not balanced or has no pot, or every member is retired, or the member's dates do not include the
 *  sheet's today — such a member is left out of the total share and balance too). A pool that is a member of
 *  none has the sheet's pot; a pool that is a member of another has its cut there as its pot. */
export type PoolMember = { personId: number | null; poolId: number | null; name: string; share: string; cut: string };

export const poolsQueryKey = (sheetId: string) => ['sheet', sheetId, 'pools'] as const;

export const poolsPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/pools`;

/** The sheet's pools, in the order they were added. */
export function usePools() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: poolsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Pool[]>(poolsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { usePeople } from '../people/people';
import { poolsPath, poolsQueryKey, usePools, type Pool } from './pools';

// The sheet's pools, each with its members (with their cut of the pot when the pool is balanced), total share and whether it is balanced, and the entry that adds a pool.
// A blank name, or one already a pool's, is refused by the server and shows the error beside the entry, which goes
// as soon as the entry changes.
function Pools() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const pools = usePools();
  const [name, setName] = useState('');
  const queryClient = useQueryClient();
  const add = useMutation({
    mutationFn: (body: { name: string }) => postJson<Pool[]>(poolsPath(sheet ?? ''), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: poolsQueryKey(sheet ?? '') });
      setName('');
    },
  });
  const submit = useSubmitOnce(add);

  if (!user || !sheet) return null;
  return (
    <section data-testid="pools">
      <h2>Pools</h2>
      <table>
        <thead>
          <tr><th>Pool</th><th>Members</th><th>Total share</th><th>Balanced</th><th>Add member</th></tr>
        </thead>
        <tbody>
          {(pools.data ?? []).map((p) => <PoolRow key={p.id} pool={p} pools={pools.data ?? []} />)}
        </tbody>
      </table>
      <form
        data-testid="pool-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ name });
        }}
      >
        <input
          data-testid="pool-form-name"
          placeholder="Pool name"
          value={name}
          onChange={(e) => { setName(e.target.value); add.reset(); }}
        />
        <button type="submit" data-testid="pool-form-submit" disabled={add.isPending}>
          Add pool
        </button>
        {add.isError && (
          <span data-testid="pool-form-error">A pool's name must not be blank or already a pool's.</span>
        )}
      </form>
    </section>
  );
}

// A pool's row: its members with their shares, its total and balance, and the member select (a person, or another
// pool as pool:<name>) and share that add a member. A person already in the pool, a pool already a member of one, one
// that would contain itself or make a chain of pools more than three deep, or a share that is not more than 0.00 and
// at most 100.00 (two decimals), or a to-date before the from-date (both optional), is refused and shows the error on the pool, which goes as soon as the entry changes.
function PoolRow({ pool, pools }: { pool: Pool; pools: Pool[] }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const [memberKey, setMemberKey] = useState('');
  const [share, setShare] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const queryClient = useQueryClient();
  const add = useMutation({
    mutationFn: (body: { personId: number | null; memberPoolId: number | null; share: string; from: string; to: string }) =>
      postJson<Pool[]>(`${poolsPath(sheet ?? '')}/${pool.id}/members`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: poolsQueryKey(sheet ?? '') });
      setShare('');
      setFrom('');
      setTo('');
    },
  });
  const submit = useSubmitOnce(add);
  return (
    <tr data-testid={`pool-row-${pool.name}`}>
      <td data-testid="pool-name">{pool.name}</td>
      <td>
        <ul>
          {pool.members.map((m) => (
            <li
              key={m.poolId != null ? `pool-${m.poolId}` : m.personId}
              data-testid={m.poolId != null ? `pool-member-${pool.name}-pool-${m.name}` : `pool-member-${pool.name}-${m.personId}`}
            >
              <span data-testid="pool-member-name">{m.name}</span>{' '}
              <span data-testid="pool-share">{m.share}</span>{' '}
              <span data-testid="pool-cut">{m.cut}</span>
            </li>
          ))}
        </ul>
      </td>
      <td data-testid="pool-total-share">{pool.totalShare}</td>
      <td data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</td>
      <td>
        <select
          data-testid="pool-member-select"
          value={memberKey}
          onChange={(e) => { setMemberKey(e.target.value); add.reset(); }}
        >
          <option value="">Choose a person or pool</option>
          {(people.data ?? []).map((p) => (
            <option key={p.id} value={String(p.id)}>{p.name}</option>
          ))}
          {pools.map((p) => (
            <option key={`pool-${p.id}`} value={`pool:${p.id}`}>{`pool:${p.name}`}</option>
          ))}
        </select>
        <input
          data-testid="pool-member-share"
          placeholder="Share %"
          value={share}
          onChange={(e) => { setShare(e.target.value); add.reset(); }}
        />
        <input
          data-testid="pool-member-from"
          placeholder="from (open)"
          value={from}
          onChange={(e) => { setFrom(e.target.value); add.reset(); }}
        />
        <input
          data-testid="pool-member-to"
          placeholder="to (open)"
          value={to}
          onChange={(e) => { setTo(e.target.value); add.reset(); }}
        />
        <button
          type="button"
          data-testid="pool-member-add"
          disabled={add.isPending}
          onClick={() => submit({
            personId: memberKey === '' || memberKey.startsWith('pool:') ? null : Number(memberKey),
            memberPoolId: memberKey.startsWith('pool:') ? Number(memberKey.slice('pool:'.length)) : null,
            share,
            from,
            to,
          })}
        >
          Add member
        </button>
        {add.isError && (
          <span data-testid="pool-error">A member must not already be in the pool (a pool in at most one, never itself, at most three deep), with a share above 0.00 and at most 100.00, and a to-date not before the from-date.</span>
        )}
      </td>
    </tr>
  );
}

export const contribution = HomeMain.fill({ order: 6.7, Component: Pools });
import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import type { Person } from '../people/people';
import { usePools, type Pool } from './pools';

/** The cuts of the given person (every person when null) across every pool they are a member of, added up; a pool
 *  that shows no cuts adds nothing. Summed in whole cents, so the total is exact. */
function cutTotalOf(pools: Pool[], personId: number | null): string {
  const cents = pools
    .flatMap((p) => p.members)
    .filter((m) => m.personId != null && (personId == null || m.personId === personId) && m.cut !== '')
    .reduce((n, m) => n + Math.round(Number(m.cut) * 100), 0);
  return (cents / 100).toFixed(2);
}

// A person's cut total: their cuts across every pool they are a member of, added up.
function CutTotalHeader() {
  return <th>Cut total</th>;
}

function PersonCutTotal({ person }: { person: Person }) {
  const pools = usePools();
  return <td data-testid="person-cut-total">{cutTotalOf(pools.data ?? [], person.id)}</td>;
}

// The sheet's cut total: everyone's cut total added up.
function CutTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const pools = usePools();
  if (!user || !sheet) return null;
  return (
    <p>
      Cut in total <strong data-testid="rollup-cut-total">{cutTotalOf(pools.data ?? [], null)}</strong>
    </p>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 10.5, Component: CutTotalHeader }),
  PersonCells.fill({ order: 10.5, Component: PersonCutTotal }),
  HomeMain.fill({ order: 30.5, Component: CutTotal }),
];

